fn is_prime(n: i8) -> bool {
    // According to the problem definition:
    // - return true if and only if n >= 2 and for every integer k with 2 ≤ k < n,
    //   n % k != 0 (i.e., n is prime).
    // - return false otherwise.

    if n < 2 {
        return false;
    }

    let n_usize = n as usize;

    // Loop invariant:
    // - n >= 2 (stated above)
    // - candidate divisor k in [2, n]
    // - for all previously checked j with 2 ≤ j < k, n % j != 0
    // Termination measure: n - k decreases with each iteration (starting at k=2)
    
    let mut k = 2usize;
    while k < n_usize {
        if n_usize % k == 0 {
            // Found a divisor => n is not prime
            return false;
        }
        k += 1;
    }

    // No divisors found => n is prime
    true
}